import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SheetView {
  id: string;
  today: string;
  archived: boolean;
}

// The signed-in user and the active sheet. Every request after sign-in names the user in X-User.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheet = signal<string | null>(null);
  /** The active sheet's own today (yyyy-mm-dd), whatever date the screen shows it as of. */
  private readonly sheetToday = signal<string | null>(null);
  /**
   * The date this screen shows the sheet as of (yyyy-mm-dd), or null for the sheet as it stands. While set,
   * every read is of the sheet as it stood at the end of that date and every change is refused.
   */
  readonly asOf = signal<string | null>(null);
  /** The active sheet's today (yyyy-mm-dd): every date the screen decides on or defaults to; the as-of date while set. */
  readonly today = computed(() => this.asOf() ?? this.sheetToday());
  /** Whether the active sheet is archived: it stays visible and every change to it is refused. */
  readonly archived = signal(false);
  /** Bumped on every sheet load, so what is shown for the sheet is re-read even for the same id. */
  readonly loads = signal(0);

  async signIn(name: string): Promise<void> {
    const res = await firstValueFrom(this.http.post<{ name: string }>('/api/signin', { name }));
    this.sheet.set(null);
    this.sheetToday.set(null);
    this.asOf.set(null);
    this.archived.set(false);
    this.loads.update((n) => n + 1);
    this.user.set(res.name);
  }

  async loadSheet(id: string): Promise<void> {
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    this.sheet.set(res.id);
    this.sheetToday.set(res.today);
    this.archived.set(res.archived);
    if (this.asOf() !== null) await this.readShown(res.id);
    this.loads.update((n) => n + 1);
  }

  /** Show the active sheet as of a date (yyyy-mm-dd), or as it stands (null): everything shown is re-read. */
  async setAsOf(date: string | null): Promise<void> {
    this.asOf.set(date);
    const id = this.sheet();
    if (id) await this.readShown(id);
    this.loads.update((n) => n + 1);
  }

  /** Re-read whether the sheet is archived, as it is shown (as of the as-of date while one is set). */
  private async readShown(id: string): Promise<void> {
    const res = await firstValueFrom(this.http.get<SheetView>(`/api/sheets/${encodeURIComponent(id)}`));
    if (this.sheet() === res.id) this.archived.set(res.archived);
  }

  async setToday(today: string): Promise<void> {
    const id = this.sheet();
    if (!id) return;
    const res = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    if (this.sheet() === res.id) this.sheetToday.set(res.today);
  }

  async archive(): Promise<void> {
    const id = this.sheet();
    if (!id) return;
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    if (this.sheet() === res.id) this.archived.set(res.archived);
  }
}
import { Component, inject, signal } from '@angular/core';
import { Session } from '../../core/session';
import { People } from '../people/people';

// The one screen: sign in by name, then load a sheet by id.
@Component({
  selector: 'app-home',
  imports: [People],
  template: `
    @if (session.user(); as user) {
      <section aria-label="Session">
        <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>
        <form (submit)="load($event)">
          <label for="sheet-id">Sheet id</label>
          <input
            id="sheet-id"
            data-testid="sheet-id-input"
            [value]="sheetInput()"
            (input)="sheetInput.set(value($event)); sheetError.set('')"
          />
          <button type="submit" data-testid="sheet-load">Load</button>
          @if (sheetError()) {
            <p role="alert" data-testid="sheet-error">{{ sheetError() }}</p>
          }
        </form>
        @if (session.sheet(); as sheet) {
          <p>Sheet <strong data-testid="sheet-current-id">{{ sheet }}</strong></p>
          <form (submit)="saveToday($event)" aria-label="Sheet today">
            <p>Today <strong data-testid="sheet-today">{{ session.today() }}</strong></p>
            <label for="sheet-today-input">Set today</label>
            <input
              id="sheet-today-input"
              type="date"
              data-testid="sheet-today-input"
              [value]="todayInput()"
              (input)="todayInput.set(value($event)); sheetError.set('')"
            />
            <button type="submit" data-testid="sheet-today-save">Set today</button>
          </form>
          <form (submit)="setAsOf($event)" aria-label="Sheet as of">
            <p>As of <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong></p>
            <label for="asof-date">Show the sheet as of</label>
            <input
              id="asof-date"
              type="date"
              data-testid="asof-date"
              [value]="asOfInput()"
              (input)="asOfInput.set(value($event)); sheetError.set('')"
            />
            <button type="submit" data-testid="asof-set">Set as of</button>
            <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
          </form>
          <p>
            Archived <strong data-testid="sheet-archived">{{ session.archived() ? 'yes' : 'no' }}</strong>
            <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>
          </p>
          <app-people />
        }
      </section>
    } @else {
      <form (submit)="signIn($event)" aria-label="Sign in">
        <label for="signin-name">Name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="nameInput()"
          (input)="nameInput.set(value($event)); signinError.set('')"
        />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signinError()) {
          <p role="alert" data-testid="signin-error">{{ signinError() }}</p>
        }
      </form>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');

