            PersonRepository people, RateRepository rates, SheetSettingRepository settings, JsonMapper json) {
        this.dayEnds = dayEnds;
        this.sheets = sheets;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.json = json;
